for r in q(f"SELECT day, type, substr(message,1,160) m FROM notifications WHERE day>={lo} AND type NOT IN ('large_customer_message','deal_won','lead_lost') ORDER BY notification_id"): print(r)
print("=== SERVICE ===")
for r in q(f"SELECT day, total_usage_units u, ROUND(p95_ms) p95, ROUND(error_rate,4) err, downtime_minutes dt, capacity_tier ct FROM service_day WHERE day>={lo} ORDER BY day"): print(r)
