for r in q(\"\"\"SELECT l.day, COUNT(*) n, ROUND(SUM(l.amount),0) amt FROM ledger l WHERE l.category='subscription_payment' AND l.day>=78 AND CAST(substr(l.note, 35) AS INTEGER) IN (SELECT customer_id FROM customers WHERE customer_type='large') GROUP BY l.day\"\"\"): print(r)
print('=== thread types seen ===')
for r in q('SELECT thread_type, COUNT(DISTINCT thread_id) n FROM enterprise_turns GROUP BY 1'): print(r)
print('=== S2 renewal cohort 48-54 ===')
for r in q(\"SELECT s.status, COUNT(*) n FROM subscriptions s JOIN customers c USING(customer_id) WHERE c.group_id='S2' AND s.start_day BETWEEN 48 AND 54 AND s.status IN ('subscribed','cancelled') GROUP BY 1\"): print(r)
print('=== retail renewals: payments this week from subs started <= day 54 ===')
for r in q(\"\"\"SELECT COUNT(*) n, ROUND(SUM(l.amount),0) amt FROM ledger l WHERE l.category='subscription_payment' AND l.day>=78 AND CAST(substr(l.note, 35) AS INTEGER) IN (SELECT customer_id FROM customers WHERE customer_type='small' AND created_day<=54)\"\"\"): print(r)
" 2>&1 | grep -v request_id

