./novamind-operation python-c "
import novamind_api as nm
q = lambda s: nm.query(s)['rows']
print('=== first renewals due this week (started 118-124) ===')
for r in q(\"SELECT c.group_id g, s.plan, SUM(CASE WHEN s.status='cancelled' THEN 1 ELSE 0 END) canc, SUM(CASE WHEN s.status='subscribed' THEN 1 ELSE 0 END) kept FROM subscriptions s JOIN customers c USING(customer_id) WHERE c.customer_type='small' AND s.start_day BETWEEN 118 AND 124 AND s.status IN ('subscribed','cancelled') GROUP BY 1,2 ORDER BY 1,2\"): print(r)
print('=== cancellations this week by group/plan (retail) ===')
for r in q(\"SELECT c.group_id g, s.plan, COUNT(*) n FROM subscriptions s JOIN customers c USING(customer_id) WHERE s.status='cancelled' AND s.end_day>147 AND c.customer_type='small' GROUP BY 1,2 ORDER BY 3 DESC LIMIT 12\"): print(r)
print('=== enterprise cancellations this week ===')
for r in q(\"SELECT c.group_id g, COUNT(*) n, SUM(s.seat_count) seats FROM subscriptions s JOIN customers c USING(customer_id) WHERE s.status='cancelled' AND s.end_day>147 AND c.customer_type='large' GROUP BY 1\"): print(r)
print('=== notifications non-lead ===')
for r in q(\"SELECT day, type, substr(message,1,100) m FROM notifications WHERE day>147 AND type NOT IN ('large_customer_message','deal_won','lead_lost') ORDER BY notification_id\"): print(r)
print('=== competitor posts ===')
for r in q(\"SELECT post_id, day, substr(content,1,100) c FROM social_media_posts WHERE day>147 AND (content LIKE '%overhaul%' OR content LIKE '%raised the bar%') ORDER BY post_id DESC LIMIT 5\"): print(r)
print('=== quota complaints ===')
for r in q(\"SELECT post_id, day, substr(content,1,120) c FROM social_media_posts WHERE day>147 AND (content LIKE '%limit%' OR content LIKE '%quota%' OR content LIKE '%throttl%') ORDER BY post_id DESC LIMIT 5\"): print(r)
print('=== retail base ===')
for r in q(\"SELECT c.group_id g, COUNT(*) n, ROUND(SUM(s.effective_price),0) mrr FROM subscriptions s JOIN customers c USING(customer_id) WHERE s.status='subscribed' AND c.customer_type='small' GROUP BY 1 ORDER BY 3 DESC LIMIT 9\"): print(r)
" 2>&1 | grep -v request_id

