arguments.command:
./novamind-operation python-c "
import novamind_api as nm
q = lambda s: nm.query(s)['rows']
print('=== retail cancellations this week by group/plan/tenure (n>=150) ===')
for r in q(\"SELECT c.group_id g, s.plan, CAST((s.end_day-s.start_day)/30 AS INTEGER)*30 ten, COUNT(*) n FROM subscriptions s JOIN customers c USING(customer_id) WHERE s.status='cancelled' AND s.end_day>175 AND c.customer_type='small' GROUP BY 1,2,3 HAVING n>=150 ORDER BY 4 DESC\"): print(r)
print('=== first renewals due this week (started 146-152) ===')
for r in q(\"SELECT c.group_id g, s.plan, SUM(CASE WHEN s.status='cancelled' THEN 1 ELSE 0 END) canc, SUM(CASE WHEN s.status='subscribed' THEN 1 ELSE 0 END) kept FROM subscriptions s JOIN customers c USING(customer_id) WHERE c.customer_type='small' AND s.start_day BETWEEN 146 AND 152 AND s.status IN ('subscribed','cancelled') GROUP BY 1,2 HAVING canc+kept>=200 ORDER BY 1,2\"): print(r)
print('=== renewals of OLD cohorts this week: subs started 56-62 (tenure 120) ===')
for r in q(\"SELECT c.group_id g, s.plan, SUM(CASE WHEN s.status='cancelled' AND s.end_day>175 THEN 1 ELSE 0 END) canc_this_week, SUM(CASE WHEN s.status='subscribed' THEN 1 ELSE 0 END) kept FROM subscriptions s JOIN customers c USING(customer_id) WHERE c.customer_type='small' AND c.group_id='S2' AND s.start_day BETWEEN 56 AND 62 GROUP BY 1,2\"): print(r)
print('=== cancellations by day ===')
for r in q(\"SELECT end_day d, COUNT(*) n FROM subscriptions WHERE status='cancelled' AND end_day>175 GROUP BY 1 ORDER BY 1\"): print(r)
print('=== enterprise cancellations this week ===')
for r in q(\"SELECT c.group_id g, COUNT(*) n, SUM(s.seat_count) seats FROM subscriptions s JOIN customers c USING(customer_id) WHERE s.status='cancelled' AND s.end_day>175 AND c.customer_type='large' GROUP BY 1\"): print(r)
print('=== notifications non-lead ===')
for r in q(\"SELECT day, type, substr(message,1,120) m FROM notifications WHERE day>175 AND type NOT IN ('large_customer_message','deal_won','lead_lost') ORDER BY notification_id\"): print(r)
print('=== competitor posts ===')
for r in q(\"SELECT post_id, day, substr(content,1,100) c FROM social_media_posts WHERE day>175 AND (content LIKE '%overhaul%' OR content LIKE '%raised the bar%' OR content LIKE '%launch%') ORDER BY post_id DESC LIMIT 6\"): print(r)
print('=== complaint posts ===')
for r in q(\"SELECT post_id, day, substr(content,1,140) c FROM social_media_posts WHERE day>175 AND (content LIKE '%outage%' OR content LIKE '%limit%' OR content LIKE '%cancel%' OR content LIKE '%switch%') ORDER BY post_id DESC LIMIT 6\"): print(r)
print('=== retail base ===')
for r in q(\"SELECT c.group_id g, COUNT(*) n, ROUND(SUM(s.effective_price),0) mrr FROM subscriptions s JOIN customers c USING(customer_id) WHERE s.status='subscribed' AND c.customer_type='small' GROUP BY 1 ORDER BY 3 DESC LIMIT 9\"): print(r)
" 2>&1 | grep -v request_id

