print('=== enterprise plan distribution ===')
for r in q(\"SELECT s.plan, COUNT(*) n, SUM(s.seat_count) seats, ROUND(SUM(s.seat_count*s.effective_price),0) mrr FROM subscriptions s JOIN customers c USING(customer_id) WHERE s.status='subscribed' AND c.customer_type='large' GROUP BY 1\"): print(r)
print('=== sample customer posts this week ===')
for r in q(\"SELECT post_id, day, substr(content,1,260) c FROM social_media_posts WHERE day>231 ORDER BY post_id DESC LIMIT 14\"): print(r['post_id'], r['day'], repr(r['c']))
" 2>&1 | grep -v request_id

