cat > strategy/ent_lib.py <<'EOF'
import novamind_api as nm, json, re
def show(label, r): print(label, json.dumps(r, default=str)[:300])
def send(deals, label):
    ok = 0; bad = []
    for i in range(0, len(deals), 40):
        res = nm.enterprise.send_enterprise_deal(deals[i:i+40])
        ok += sum(1 for x in res['results'] if x.get('success')); bad += [x for x in res['results'] if not x.get('success')]
    print(label, "ok:", ok, "of", len(deals), bad[:5])
q = lambda s: nm.query(s)['rows']
def price_in(m):
    mm = re.search(r'\$([0-9]+(?:\.[0-9]+)?)', m or ''); return float(mm.group(1)) if mm else None
def plan_in(m):
    mm = re.search(r'Plan ([ABC])', m or ''); return mm.group(1) if mm else None
LOWER = {"C": "B", "B": "A"}
OFFERS = {"E1": [["A", 25.0], ["B", 44.0], ["C", 65.0]], "E2": [["B", 85.0], ["C", 135.0]], "E3": [["B", 85.0], ["C", 109.0]],
          "D_E09": [["A", 29.0], ["B", 59.0], ["C", 79.0]], "D_E02": [["A", 29.0], ["B", 55.0], ["C", 75.0]],
          "D_E08": [["B", 89.0], ["C", 125.0]], "D_E07": [["B", 105.0], ["C", 145.0]],
          "D_E01": [["B", 99.0], ["C", 135.0]], "D_E03": [["B", 119.0], ["C", 165.0]],
          "D_E05": [["B", 89.0], ["C", 125.0]], "D_E10": [["A", 29.0], ["B", 55.0]], "D_E04": [["B", 125.0], ["C", 165.0]],
          "D_E06": [["B", 75.0], ["C", 99.0]]}
def counter(g, pl, p, t):
    if g == "E2":
        if p >= 40: return [["B", p], ["C", p+40]]
        if t >= 4 and p >= 22: return [["B", p]]
        return [["B", 42]] if p >= 26 else [["B", 38]]
    if g == "E3":
        if p >= 23: return [["B", p], ["C", p+25]]
        if t >= 4 and p >= 15: return [["B", p]]
        return [["B", 27], ["C", 49]]
    if g == "E1":
        if pl == "A": return [["A", p], ["B", p+12]] if p >= 8 else [["A", 10]]
        if pl == "C":
            if p >= 24: return [["C", p], ["B", p-10]]
            if t >= 4 and p >= 18: return [["C", p]]
            return [["C", 28], ["B", 19]]
        if p >= 16: return [["B", p], ["C", p+14]]
        if t >= 4 and p >= 11: return [["B", p]]
        return [["B", 19], ["A", 11]]
    if g in ("D_E09", "D_E02"):
        if pl == "A": return [["A", p], ["B", p+30]] if (p >= 8 or (t >= 4 and p >= 5)) else [["A", 9], ["B", 35]]
        if pl == "C": return [["C", p], ["B", max(p-20, 20)]] if (p >= 28 or (t >= 4 and p >= 20)) else [["C", 45], ["B", 29]]
        return [["B", p], ["C", p+20]] if (p >= 18 or (t >= 4 and p >= 12)) else [["B", 25], ["A", 14]]
    if g in ("D_E08", "D_E06"):
        if pl == "C": return [["C", p], ["B", max(p-30, 30)]] if (p >= 40 or (t >= 4 and p >= 30)) else [["B", 35], ["C", 65]]
        return [["B", p], ["C", p+30]] if (p >= 30 or (t >= 4 and p >= 22)) else [["B", 35], ["C", 65]]
    if g == "D_E07":
        if pl == "C": return [["C", p], ["B", p-30]] if p >= 60 else [["C", 89], ["B", 55]]
        return [["B", p], ["C", p+40]] if (p >= 40 or (t >= 4 and p >= 30)) else [["B", 49], ["C", 89]]
    if g in ("D_E01", "D_E03", "D_E05", "D_E04"):
        if pl == "C": return [["C", p], ["B", max(p-30, 35)]] if p >= 55 else [["C", 89], ["B", 59]]
        return [["B", p], ["C", p+40]] if (p >= 40 or (t >= 4 and p >= 28)) else [["B", 55], ["C", 95]]
    if g == "D_E10":
        if pl == "A": return [["A", p], ["B", p+15]] if p >= 9 else [["A", 12], ["B", 29]]
        return [["B", p]] if p >= 22 else [["A", 15], ["B", 29]]
    return [["B", max(p, 40)]]

def respond_all(ret_same=0.8, ret_lower=0.6, floor=None, acc_floor=None, dry=False):
    floor = floor or {"A": 5.0, "B": 22.0, "C": 30.0}
    acc_floor = acc_floor or {"A": 8.0, "B": 22.0, "C": 30.0}
    rows = q('''SELECT t.thread_id, t.customer_id cid, c.group_id g, t.thread_type tt, t.turn_number turn, t.sender, t.seat_count seats,
       substr(t.message_text,1,200) m, s.plan, s.effective_price px, s.status
     FROM enterprise_turns t JOIN customers c USING(customer_id)
     LEFT JOIN subscriptions s ON s.customer_id=t.customer_id AND s.subscription_id=(SELECT MAX(subscription_id) FROM subscriptions y WHERE y.customer_id=t.customer_id)
     WHERE t.message_id IN (SELECT MAX(message_id) FROM enterprise_turns GROUP BY thread_id) AND t.closed=0 AND t.sender!='agent' ''')
    retention, churn_ctr, lead_ctr, openers, other = [], [], [], [], []
    for r in rows:
        if r['tt'] == 'churn_prevention' and r['status'] == 'subscribed' and r['sender'] == 'customer':
            if r['turn'] == 1:
                p = r['px']; d = [[r['plan'], max(floor[r['plan']], round(p*ret_same))]]
                if r['plan'] in LOWER: d.append([LOWER[r['plan']], max(floor[LOWER[r['plan']]], round(p*ret_lower))])
                retention.append([r['cid'], d])
            else:
                cp = price_in(r['m']); pl = plan_in(r['m']) or r['plan']
                if cp is None: other.append(r); continue
                churn_ctr.append([r['cid'], [[pl, cp if cp >= acc_floor[pl] else acc_floor[pl]]]])
        elif r['tt'] == 'new_lead' and r['sender'] == 'system' and r['turn'] == 0:
            openers.append([r['cid'], OFFERS.get(r['g'], [["B", 69.0], ["C", 99.0]])])
        elif r['tt'] == 'new_lead' and r['sender'] == 'customer':
            p = price_in(r['m']); pl = plan_in(r['m']) or "B"
            if p is None: other.append(r); continue
            lead_ctr.append([r['cid'], counter(r['g'], pl, p, r['turn'])])
        else:
            other.append(r)
    print("retention", len(retention), "churn counters", len(churn_ctr), "lead counters", len(lead_ctr), "openers", len(openers), "other", len(other))
    for r in other[:10]: print("  OTHER:", r['g'], r['tt'], r['sender'], r['turn'], r['status'], repr(r['m'][:120]))
    if dry: return
    if retention: send(retention, "retention")
    if churn_ctr: send(churn_ctr, "churn-counters")
    if lead_ctr: send(lead_ctr, "lead-counters")
    if openers: send(openers, "openers")
