cat > strategy/act_w45.py <<'EOF'
import sys, re, collections; sys.path.insert(0, 'strategy')
import ent_lib
from ent_lib import *
show("tiers", nm.pricing.set_model_tiers(A=2, B=4, C=4))
for tier in [1, 2, 4, 6]:
    try: show(f"research t{tier}", nm.research.start_research_project(tier))
    except Exception as e: print("research", tier, "ERR", str(e)[:160])
# look at counter asks before responding
rows = q('''SELECT c.group_id g, s.plan, s.effective_price px, substr(t.message_text,1,60) m FROM enterprise_turns t JOIN customers c USING(customer_id)
 JOIN subscriptions s ON s.customer_id=t.customer_id AND s.status='subscribed'
 WHERE t.message_id IN (SELECT MAX(message_id) FROM enterprise_turns GROUP BY thread_id) AND t.closed=0 AND t.sender='customer' AND t.thread_type='churn_prevention' AND t.turn_number>=3''')
byg = collections.defaultdict(list)
for r in rows:
    mm = re.search(r'\$([0-9.]+)', r['m'])
    if mm and r['px']: byg[r['g']].append(round(float(mm.group(1))/r['px'], 2))
for g, v in byg.items():
    v.sort(); print("counter asks", g, "n", len(v), "ratio quartiles", v[len(v)//4], v[len(v)//2], v[3*len(v)//4])
respond_all(ret_same=0.7, ret_lower={"C": 0.7, "B": 0.5, "A": 0.5}, floor={"A": 6.0, "B": 22.0, "C": 30.0}, acc_floor={"A": 6.0, "B": 24.0, "C": 32.0})
show("post", nm.marketing.post_social_media("Today every Pro and Max plan moves to our frontier model class at no extra cost: materially higher reasoning quality, same price, same quotas. Combined with last week's price cuts, this is the biggest value upgrade we have shipped. Try it and tell us. #NovaMind"))
EOF
./novamind-operation python strategy/act_w45.py 2>&1 | grep -v request_id

